// Makes version 5 libraries (.lbr) with the old MetaboliteDetector 3.3 (Linux) and prints what the
// old program reads back from them. See make-lbr-v5.sh for how it is used.
//
// Loaded with LD_PRELOAD into the old binary: it replaces main() and calls the binary's own library
// code by address (syms.inc, generated by make-lbr-v5.sh from `nm`). The old writer always writes
// version 5 (LibraryCompound::toDisk), so reading the version 2 sample and saving it gives a v5 file.
#include <dlfcn.h>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

namespace {

uintptr_t base;

template <class F> F fn(uintptr_t addr) { return reinterpret_cast<F>(base + addr); }

#define SYM(name, addr) constexpr uintptr_t name = addr;
#include "syms.inc"
#undef SYM

using Self = const void*;
using Lib = std::vector<void*>;  // std::vector<LibraryCompound*>

template <class T> T at(Self p, size_t off) {
    T v;
    std::memcpy(&v, static_cast<const char*>(p) + off, sizeof v);
    return v;
}

// PeakEssential<T> members, offsets from its toStream/fromStream (file-formats.md §1.6).
void peak_fields(FILE* out, Self p, bool short_ion) {
    double ion = short_ion ? at<int16_t>(p, 0x08) : at<float>(p, 0x08);
    std::fprintf(out, "%.9g\t%.17g\t%.17g\t%.17g\t%.17g\t%zu\t%u\t%u\t%.17g\t%u\t%.17g", ion,
                 at<double>(p, 0x10), at<double>(p, 0x20), at<double>(p, 0x18), at<double>(p, 0x28),
                 at<size_t>(p, 0x30), at<unsigned>(p, 0x38), at<unsigned>(p, 0x3c), at<double>(p, 0x50),
                 at<unsigned>(p, 0x40), at<double>(p, 0x48));
}

Lib read(const char* file) {
    Lib lib;
    fn<void (*)(Lib*, const char*)>(LC_FROM_DISK)(&lib, file);
    return lib;
}

void write(const Lib& lib, const char* file) { fn<void (*)(const Lib&, const char*)>(LC_TO_DISK)(lib, file); }

// What the old program reads back: name, peaks and the model peak of every compound.
void dump(FILE* out, const char* file) {
    std::fprintf(out, "lib\t%s\n", std::strrchr(file, '/') + 1);
    for (void* c : read(file)) {
        alignas(8) char buf[sizeof(std::vector<Self>)];
        fn<void (*)(void*, Self)>(COMPOUND_PEAKS)(buf, c);
        auto* peaks = reinterpret_cast<std::vector<Self>*>(buf);
        std::fprintf(out, "compound\t%s\t%zu\n", at<const char*>(c, 0x78), peaks->size());
        for (Self p : *peaks) {
            std::fputs("peak\t", out);
            peak_fields(out, p, false);
            std::fputc('\n', out);
        }
        peaks->~vector();
        Self m = at<Self>(c, 0x70);  // std::unique_ptr<Peak<double,short>>
        auto values = at<const double*>(m, 0x60);
        size_t n = at<const double*>(m, 0x68) - values;
        std::fputs("model\t", out);
        peak_fields(out, m, true);
        std::fprintf(out, "\t%.17g\t%zu", at<double>(m, 0x58), n);
        for (size_t i = 0; i < n; i++) std::fprintf(out, "\t%.17g", values[i]);
        std::fputc('\n', out);
    }
}

// Peaks and model of compounds from a real run: CdfImporter -> GCMSDiskScan -> GCMSAnalyzer, as in
// old_md_dump.cpp, then LibrarySearch(vector<Compound*>) and its toDisk.
void from_run(const char* cdf, const std::string& dir) {
    std::string stem = dir + "/run";
    alignas(16) static char importer[1 << 16];
    fn<void (*)(void*, const char*)>(CDF_IMPORTER_CTOR)(importer, cdf);
    fn<void (*)(void*, const char*)>(CDF_IMPORT_DATA)(importer, stem.c_str());
    fn<void (*)(void*)>(CDF_IMPORTER_DTOR)(importer);
    void* scan = ::operator new(0x390);
    fn<void (*)(void*, const char*, bool, bool, void*)>(DISK_SCAN_CTOR)(scan, stem.c_str(), false, false, nullptr);
    void* detector = ::operator new(0x20);
    fn<void (*)(void*)>(DEFAULT_DETECTOR_CTOR)(detector);
    auto* an = static_cast<char*>(::operator new(0xb0));
    fn<void (*)(void*, void*, void*)>(ANALYZER_CTOR)(an, scan, detector);
    const float scan_dist = 10.0f, ion_dist = 0.05f;
    fn<bool (*)(void*, bool, const float&, const float&)>(DETECT_ALL_PEAKS)(an, true, scan_dist, ion_dist);
    fn<void (*)(void*)>(DECONVOLUTE)(an);
    auto* comps = reinterpret_cast<std::vector<void*>*>(an + 0x58);
    std::vector<void*> some(comps->begin(), comps->begin() + std::min<size_t>(comps->size(), 20));
    alignas(16) static char search[1 << 16];
    fn<void (*)(void*, const std::vector<void*>&)>(LS_CTOR_COMPOUNDS)(search, some);
    fn<void (*)(Self, const char*)>(LS_TO_DISK)(search, (dir + "/run_v5.lbr").c_str());
}

// usage: LD_PRELOAD=lbr_v5.so metabolitedetector_app OUT_DIR lib_aa.lbr [RUN.cdf]
int lbr_main(int argc, char** argv, char**) {
    if (argc < 3) {
        std::fprintf(stderr, "usage: %s OUT_DIR lib_aa.lbr [RUN.cdf]\n", argv[0]);
        return 2;
    }
    std::string dir = argv[1];
    std::string conv = dir + "/lib_aa_v5.lbr", frag = dir + "/fragments_v5.lbr";
    std::string msl = dir + "/lib_aa.msl", msl_lib = dir + "/msl_v5.lbr";

    Lib lib = read(argv[2]);
    write(lib, conv.c_str());

    // Formulas and mid sizes: addFragment trims the formula.
    using AddFragment = void (*)(void*, unsigned long, unsigned long, const std::string&, unsigned long);
    fn<AddFragment>(LC_ADD_FRAGMENT)(lib[0], 73, 147, std::string(" C3H9Si "), 2);
    fn<AddFragment>(LC_ADD_FRAGMENT)(lib[0], 5, 6, std::string("N"), 0);
    fn<AddFragment>(LC_ADD_FRAGMENT)(lib[1], 40, 41, std::string("Ar"), 1);
    write(lib, frag.c_str());

    // MSL round trip through the old exporter and importer.
    alignas(16) static char search[1 << 16];
    fn<void (*)(void*, const Lib&, bool)>(LS_CTOR_LIB)(search, lib, false);
    fn<void (*)(Self, const char*, unsigned)>(LS_EXPORT_MSL)(search, msl.c_str(), 0);  // MSLProfile
    // importMSL is static and returns a new LibrarySearch.
    void* imported = fn<void* (*)(const char*)>(LS_IMPORT_MSL)(msl.c_str());
    fn<void (*)(Self, const char*)>(LS_TO_DISK)(imported, msl_lib.c_str());

    if (argc > 3) from_run(argv[3], dir);

    FILE* out = std::fopen((dir + "/old.tsv").c_str(), "w");
    if (!out) { std::perror("old.tsv"); return 1; }
    for (const std::string& f : {conv, frag, msl_lib}) dump(out, f.c_str());
    if (argc > 3) dump(out, (dir + "/run_v5.lbr").c_str());
    return std::fclose(out) == 0 ? 0 : 1;
}

}  // namespace

extern "C" int __libc_start_main(int (*main)(int, char**, char**), int argc, char** argv, void (*init)(),
                                 void (*fini)(), void (*rtld_fini)(), void* stack_end) {
    base = reinterpret_cast<uintptr_t>(main) - MAIN;
    using Start = int (*)(int (*)(int, char**, char**), int, char**, void (*)(), void (*)(), void (*)(), void*);
    auto real = reinterpret_cast<Start>(dlsym(RTLD_NEXT, "__libc_start_main"));
    return real(lbr_main, argc, argv, init, fini, rtld_fini, stack_end);
}
